```json
{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, min(value) AS min_v, max(value) AS max_v, count(*) AS n FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='rate' GROUP BY metric",
          "claim": "The rate deployment reports zero available replicas across the whole abnormal window, versus one in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, max(value) AS max_restarts FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'rate-%' GROUP BY 1,2",
          "claim": "The rate pod's container restarts climb from about 3 to 6 during the window while its container never becomes ready."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_status_code, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,3) AS p50_ms FROM abnormal_traces WHERE service_name='search' AND span_name='rate.Rate/GetRates' GROUP BY 1",
          "claim": "Search's calls to rate return Error in 327 of 330 cases with about 0.02 ms median, i.e. fast connection failures."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','search.Search/Nearby') GROUP BY 1,2,3",
          "claim": "Search's rate.Rate/GetRates client spans fail almost always, and its search.Search/Nearby server spans fail in the same proportion."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code AS http_status, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND (span_name='HTTP /hotels' OR span_name='search.Search/Nearby') GROUP BY 1,2,3,4",
          "claim": "Frontend's search client calls and its HTTP /hotels requests return errors (HTTP 500) about 99% of the time."
        }
      ]
    }
  ]
}
```

